/* face-core.js — the face rig: the polygon face and its mouth model, the muscle field, the jaw, the
   springs, the expression/agent/gesture layers, the device UI and the anatomy overlay. Shared by
   facerig2.html (the face on its own) and body-face-rig.html (the face plus the 3D body).
   Load order: this file, then face-speech.js, then (body page only) the body-*.js files. */
const $ = s => document.querySelector(s);
const svg = (inner, s=16, opt={}) => {
  const sw = opt.sw ?? 1.7;
  const fill = opt.fill ? '' : ' fill="none"';
  return `<svg width="${s}" height="${s}" viewBox="0 0 24 24"${fill} stroke="currentColor" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round">${inner}</svg>`;
};
