/* The polygon face. The pixels are the wireframe mask's own polygons, traced from mask-smile.jpg:
   what you see as the mesh is what moves and colours. Around the eyes, brows, and mouth, where the
   drawing is only contour lines, an irregular triangulation sized like the drawing's cells carries the
   mesh on. Every polygon takes its own ink and its own colour, so an expression, a word, a blink, a
   wave, or a gradient is the skin itself changing. The feminine face is the same polygons moved by
   one smooth warp. */
const FACE = (() => {
  const parse = s => s.split(' ').map(p => p.split(',').map(Number));
  const pix = FACE_DATA.pix.split(';').map(parse);
  const raw = parse(FACE_DATA.sil), sil = [];
  raw.forEach((p, i) => {
    const q = raw[(i + 1) % raw.length], n = Math.max(1, Math.ceil(Math.hypot(q[0] - p[0], q[1] - p[1]) / 12));
    for(let k = 0; k < n; k++) sil.push([p[0] + (q[0] - p[0]) * k / n, p[1] + (q[1] - p[1]) * k / n]);
  });
  const lm = {eyes:[[348, 437], [680, 437]], brow:[[350, 372], [678, 372]], nose:[516, 646], nostrils:[[481, 668], [551, 668]], mouth:[516, 751]};
  return {pix, sil, lm, box:[166, 6, 700, 976]};
})();

const fSmooth = (a, b, v) => { const t = Math.min(1, Math.max(0, (v - a) / (b - a))); return t * t * (3 - 2 * t); };
const fGauss = (x, y, cx, cy, sx, sy) => Math.exp(-(((x - cx) / sx) ** 2 + ((y - cy) / sy) ** 2));
/* Base to feminine, feature by feature. Eyes a touch larger and higher; the brow ridge smoothed and
   the brows lifted; the forehead rounder; the nose narrower and shorter; the philtrum shorter and the
   lips fuller, the mouth a little narrower; cheekbones held high and full; the jaw softened below
   them; the lower face a little shorter; the chin narrowed but kept. */
