const MUSCLES = [];
(() => {
  const cen0 = FACE.pix.map(c => [c.reduce((s, p) => s + p[0], 0) / c.length, c.reduce((s, p) => s + p[1], 0) / c.length]);
  // creases draw at full strength on small polygons and only tint the big drawing cells
  const fine = FACE.pix.map(c => { let a = 0; c.forEach((p, k) => { const q = c[(k + 1) % c.length]; a += p[0] * q[1] - q[0] * p[1]; }); return Math.min(1, 200 / Math.max(1, Math.abs(a) / 2)); });
  FACE.fine = fine;
  FACE.cen0 = cen0;
  FACE.vOff = []; let nv = 0;
  FACE.pix.forEach(c => { FACE.vOff.push(nv); nv += c.length; });
  FACE.nV = nv;
  const drive = new Uint8Array(nv);
  FACE.pix.forEach((c, i) => { if(fine[i] < 1) for(let v = 0; v < c.length; v++) drive[FACE.vOff[i] + v] = 1; });
  FACE.vertDrive = drive;
  for(const [id, d] of Object.entries(MUSCLE_DEFS)){
    for(const side of d.pair ? ['L', 'R'] : ['C']){
      const mir = side === 'R', inst = {id, side, def:d, n:MUSCLES.length, verts:[], dx:[], dy:[], polys:new Set(), shadeI:[], shadeW:[], wPoly:new Float32Array(FACE.pix.length)};
      FACE.pix.forEach((c, i) => {
        c.forEach(([x, y], v) => {
          const X = mir ? 1032 - x : x;
          const w = fGauss(X, y, d.c[0], d.c[1], d.r[0], d.r[1]);
          if(w < .03) return;
          let vx, vy;
          if(d.pull){ vx = (d.c[0] - X) * d.pull[0]; vy = (d.c[1] - y) * d.pull[1]; } else { vx = d.v[0]; vy = d.v[1]; }
          inst.verts.push(FACE.vOff[i] + v); inst.dx.push((mir ? -vx : vx) * w); inst.dy.push(vy * w);
          inst.polys.add(i); inst.wPoly[i] = Math.max(inst.wPoly[i], w);
        });
        if(d.shade){ const [x, y] = cen0[i], s = Math.min(.42, d.shade(mir ? 1032 - x : x, y) * fine[i]); if(s > .02){ inst.shadeI.push(i); inst.shadeW.push(s); } }
      });
      inst.polyList = Int32Array.from(inst.polys);
      inst.shadeI = Int32Array.from(inst.shadeI); inst.shadeW = Float32Array.from(inst.shadeW);
      MUSCLES.push(inst);
    }
  }
  // the muscle each polygon belongs to most, for the map view
  FACE.dom = FACE.pix.map((_, i) => { let best = -1, bw = .25; for(const m of MUSCLES) if(m.wPoly[i] > bw){ bw = m.wPoly[i]; best = m.n; } return best; });
  // where the colour fields may go: everywhere but the eyes, brows, mouth, and nostrils, with a soft edge
  const zones = [[[348, 442], [118, 60]], [[680, 442], [118, 60]], [[346, 362], [140, 36]], [[686, 362], [140, 36]], [[516, 756], [150, 52]], [[516, 660], [62, 30]]];
  FACE.skinW = Float32Array.from(cen0.map(([x, y]) => {
    let w = 1;
    for(const [[cx, cy], [rx, ry]] of zones){ const d = Math.sqrt(((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2); w = Math.min(w, fSmooth(1, 1.4, d)); }
    return w;
  }));
})();
/* The mouth's bookkeeping, now that every polygon has an offset: which vertex copies belong to which
   mouth node, how much of each the mouth model owns, and how far the jaw carries every vertex. */
(() => {
  const M = FACE.mouth, nG = M.nGrid, o = FACE.vOff, NL = MOUTH.NL;
  M.cidx = new Int32Array(nG * 4);
  for(let q = 0; q < nG; q++) for(let v = 0; v < 4; v++) M.cidx[q * 4 + v] = o[M.p0 + q] + v;
  M.ncw = new Float32Array(M.nodes); M.bx = new Float32Array(M.nodes); M.by = new Float32Array(M.nodes);
  M.sdx = new Float32Array(M.nodes); M.sdy = new Float32Array(M.nodes); M.sdz = new Float32Array(M.nodes);
  M.ncw.fill(1);   // the mouth model owns every node of its grid; the face beyond the seam fades the field in (musApply)
  M.jw = new Float32Array(FACE.nV); const list = [];
  FACE.pix.forEach((c, i) => c.forEach((p, v) => { const w = faceJawW(p[0], p[1]); if(w > .002){ M.jw[o[i] + v] = w; list.push(o[i] + v); } }));
  M.jawList = Int32Array.from(list);
  M.fw = new Float32Array(FACE.nV); const fl = [];
  FACE.pix.forEach((c, i) => c.forEach((p, v) => { const w = faceMouthFW(p[0], p[1]); if(w > .01){ M.fw[o[i] + v] = w; fl.push(o[i] + v); } }));
  M.fList = Int32Array.from(fl);
  FACE.vPos = []; FACE.pix.forEach(c => c.forEach(p => FACE.vPos.push(p)));
  M.seamX = new Float32Array(M.cols.length * 2); M.seamY = new Float32Array(M.cols.length * 2);
  /* The face round the mouth, within MOUTH_SEAM_R of the seam: each vertex follows the seam's own move (the two
     nearest seam points, top or bottom row of a column) by a weight that is 1 at the seam and fades to 0. */
  {
    M.cornerL = M.cols.findIndex(c => c.u >= -1); M.cornerR = M.cols.length - 1 - [...M.cols].reverse().findIndex(c => c.u <= 1);
    const pts = []; M.cols.forEach((c, j) => { pts.push([c.x, c.rest[0], j * 2]); pts.push([c.x, c.rest[NL - 1], j * 2 + 1]); });
    for(const j of [0, M.cols.length - 1]) for(let l = 1; l < NL - 1; l++) pts.push([M.cols[j].x, M.cols[j].rest[l], j * 2]);   // the side seams
    const vk = [], va = [], vb = [], vw = [], vt = [];
    for(let i = 0; i < M.p0; i++) FACE.pix[i].forEach((p, v) => {
      let a = -1, b = -1, da = 1e9, db = 1e9;
      for(const [x, y, id] of pts){ const d = Math.hypot(p[0] - x, p[1] - y); if(d < da){ b = a; db = da; a = id; da = d; } else if(d < db){ b = id; db = d; } }
      if(da >= MOUTH_SEAM_R) return;
      const t = 1 - da / MOUTH_SEAM_R;
      vk.push(o[i] + v); va.push(a); vb.push(b); vt.push(db / (da + db + 1e-6)); vw.push(t * t * (3 - 2 * t));
    });
    M.seam = {k:Int32Array.from(vk), a:Int32Array.from(va), b:Int32Array.from(vb), t:Float32Array.from(vt), w:Float32Array.from(vw)};
  }
  M.fSide = new Uint8Array(FACE.nV);
  FACE.pix.forEach((c, i) => c.forEach((p, v) => { M.fSide[o[i] + v] = p[0] < M.mx ? 0 : 1; }));
  for(let q = 0; q < nG; q++) if(!M.role[M.p0 + q]) FACE.skinW[M.p0 + q] = 1;   // the skin rows around the lips take the colour fields like any skin
  FACE.silJ = FACE.sil.map(([x, y]) => faceJawW(x, y));
})();
/* An activation spec is {muscle: a} or {muscle: [left, right]}; this resolves it per muscle instance. */
function musTargets(spec, out=new Float32Array(MUSCLES.length), scale=1){
  if(!spec) return out;
  for(const m of MUSCLES){
    const v = spec[m.id]; if(v == null) continue;
    out[m.n] += scale * (Array.isArray(v) ? (m.side === 'R' ? v[1] : m.side === 'L' ? v[0] : (v[0] + v[1]) / 2) : v);
  }
  return out;
}
/* Vertex displacement and crease ink for a set of activations. The gaussian is integrated
   only on the broad cells. Refined vertices stay at rest here and sample the broad field later. */
function musApply(acts, DX, DY, shade){
  DX.fill(0); DY.fill(0); if(shade) shade.fill(0);
  const drive = FACE.vertDrive;
  for(const m of MUSCLES){
    const a = acts[m.n]; if(Math.abs(a) < .002) continue;
    for(let k = 0; k < m.verts.length; k++){
      const vi = m.verts[k];
      if(drive[vi] === 0) continue;
      DX[vi] += a * m.dx[k]; DY[vi] += a * m.dy[k];
    }
    if(shade && a > 0) for(let k = 0; k < m.shadeI.length; k++) shade[m.shadeI[k]] += a * m.shadeW[k];
  }
}

