function poseMatrix(P){
  const r = Math.PI / 180;
  return {cy:Math.cos(P.yaw * r), sy:Math.sin(P.yaw * r), cp:Math.cos(-P.pitch * r), sp:Math.sin(-P.pitch * r),
    cr:Math.cos(P.roll * r), sr:Math.sin(P.roll * r), s:P.s, tx:P.tx, ty:P.ty};
}
function project(M, x, y, z){
  const x0 = x - 516, y0 = y - 520;
  const x1 = x0 * M.cy + z * M.sy, z1 = -x0 * M.sy + z * M.cy;
  const y2 = y0 * M.cp - z1 * M.sp, z2 = y0 * M.sp + z1 * M.cp;
  const x3 = x1 * M.cr - y2 * M.sr, y3 = x1 * M.sr + y2 * M.cr;
  const k = (1900 - z) / (1900 - z2) * M.s;
  return [516 + M.tx + x3 * k, 520 + M.ty + y3 * k];
}
function facing(M, x, y, z){
  const nx = (x - 516) / 122500, ny = (y - 520) / 270400, nz = z / 57600;
  const z1 = -nx * M.sy + nz * M.cy;
  return ny * M.sp + z1 * M.cp > 0;
}
/* The layers, from the bottom up.
   Muscles are the foundation: every visible change on the face is muscle activation, a jaw opening,
   a gaze, and a blink. Expressions are named muscle recipes. Emotions are a point in a plane —
   unpleasant to pleasant, calm to aroused — that gives the face a resting muscle tone and its manner:
   palette, field, flips, blink rate, restlessness. Gestures are head movements built from a few motion
   primitives, with expression beats and micro-movements placed along them. Agent states are built
   from all of these: a point in the emotion plane, an expression held at a weight, behaviours, and
   speech. Each layer adds muscle targets; the springs in the muscles turn the sum into movement. */
