      const base = FACE_EXPRS[f.expr.name]?.look || A.gaze || [0, 0];
      f.look = Math.random() < .35 ? base.slice() : [base[0] + Math.round((Math.random() * 2 - 1) * 10), base[1] + Math.round((Math.random() * 2 - 1) * 4)];
