    if(big) g += Object.entries(EMOTIONS).filter(([k]) => k !== 'neutral').map(([k, e]) => `<text class="pa" data-emo="${k}" x="${(50 + e.va[0] * 44).toFixed(1)}" y="${(50 - e.va[1] * 38 + 2 + (k === 'surprised' ? -3 : 0)).toFixed(1)}" text-anchor="middle">${k}</text>`).join('');
