PADS.nasalBone = {label:'Nasal bone', x:['narrow','wide'], y:['short','long']};
PADS.chinBone = {label:'Chin bone', x:['narrow','wide'], y:['tuck','thrust']};
PADS.orbitBone = {label:'Orbit', x:['tilt in','tilt out'], y:['close','open']};
PADS.skin = {label:'Skin', x:['plain','flush'], y:['soft','creased']};
PADS.pupil = {label:'Pupil', x:['tight','dilated'], y:['small iris','large iris']};
PADS.gem = {label:'Gem', x:['natural','ruby'], y:['whole eye','iris only']};
const padGhostCore = padGhost;
padGhost = function(name, f, side){
  if(name === 'mandible' || name === 'zygoma' || name === 'browRidge' || name === 'nasalBone' || name === 'chinBone' || name === 'orbitBone' || name === 'skin' || name === 'pupil' || name === 'gem') return f.pad[name];
  const a = id => Math.max(-1, Math.min(1.2, f.acts[MUSCLE_IDX[id + '.' + side] ?? MUSCLE_IDX[id + '.C']] || 0));
  const c = v => Math.max(-1, Math.min(1, v));
  if(name === 'forehead') return [c(a('frontIn') - a('frontOut')), c((a('frontIn') + a('frontOut')) * .5 - a('occip'))];
  if(name === 'nose') return [c(a('nasal') - a('nasTrans')), c(a('depSept') - Math.max(a('noseWr'), a('llsan')))];
  if(name === 'upperLip') return [c(-a('incSup')), c(a('ulr'))];
  if(name === 'commissure') return [c(a('ris') - a('bucc')), c(a('zyg') - a('dao'))];
  if(name === 'lowerFace') return [c(a('dli') - a('incInf')), c(a('dli') + a('plat') * .3 - a('ment'))];
  if(name === 'neck') return [c(a('scm') + a('plat') * .3), c(a('plat') + a('digas') - a('mylo'))];
  if(name === 'glabella') return [c(-a('corr')), c(a('frontIn') * .45 - a('procerus'))];
  if(name === 'closers') return [c(Math.max(a('masseter'), a('temporalis'))), c(a('masseter') - a('temporalis'))];
  return padGhostCore(name, f, side);
};
function syncAug(f){
  if(!f || !f.pad.mandible) return;
  const b = FACE_AUG.bone;
  const m = f.pad.mandible, z = f.pad.zygoma, br = f.pad.browRidge, n = f.pad.nasalBone, c = f.pad.chinBone, o = f.pad.orbitBone;
  const next = {jaw:m[1], side:m[0], zygW:z[0], zygH:z[1], brow:br[1], browPinch:br[0], nasLen:n[1], nasW:n[0], chinT:c[1], chinW:c[0], orbOpen:o[1], orbTilt:o[0]};
  let dirty = false;
  for(const k in next) if(b[k] !== next[k]){ b[k] = next[k]; dirty = true; }
  const flush = Math.max(0, f.pad.skin[0]), crease = Math.max(0, f.pad.skin[1]);
  if(flush !== FACE_AUG.flush || crease !== FACE_AUG.crease) dirty = true;
  FACE_AUG.flush = flush; FACE_AUG.crease = crease;
  const pupil = f.pad.pupil[0], iris = .8 + Math.max(0, f.pad.pupil[1]) * .55;
  if(pupil !== FACE_AUG.pupil || iris !== FACE_AUG.iris){ dirty = true; f.eT = 0; }
  FACE_AUG.pupil = pupil; FACE_AUG.iris = iris;
  const ruby = Math.max(0, f.pad.gem[0]), marble = 1 - Math.max(0, f.pad.gem[1]);
  if(ruby !== FACE_AUG.ruby || marble !== FACE_AUG.marble) dirty = true;
  FACE_AUG.ruby = ruby; FACE_AUG.marble = marble;
  if(dirty) f.augDirty = true;
}
const facePadsCore = facePads;
facePads = function(f){ syncAug(f); facePadsCore(f); };
function boneShape(el, pts, jaw, side){
  el.setAttribute('points', pts.map(([x, y]) => {
    const jd = y < 600 ? 0 : (function(t){ t = Math.min(1, Math.max(0, (t - 600) / 340)); return t * t * (3 - 2 * t); })(y);
    return (x + side * 32 * jd).toFixed(1) + ',' + (y + jaw * 80 * jd).toFixed(1);
  }).join(' '));
}
function mountAnatomy(svg){
  const NS = 'http://www.w3.org/2000/svg';
  const g = document.createElementNS(NS, 'g');
  g.setAttribute('class', 'anat');
  const bones = [
    {name:'frontal squama', part:'squama', pts:[[516,36],[450,48],[380,78],[320,130],[278,200],[268,280],[300,340],[380,358],[460,340],[516,332]]},
    {name:'supraorbital margin', part:'brow', pair:1, pts:[[290,352],[340,334],[400,336],[460,356],[486,380],[448,396],[370,388],[314,380],[292,366]]},
    {name:'glabella', part:'glabella', pts:[[516,344],[492,338],[474,366],[484,396],[516,406]]},
    {name:'nasal bones', part:'nasal', pts:[[516,400],[502,428],[492,500],[486,568],[496,608],[516,620]]},
    {name:'anterior nasal spine', part:'spine', pts:[[516,636],[506,654],[500,686],[516,706]]},
    {name:'zygomatic body', part:'zyg', pair:1, pts:[[300,470],[355,452],[410,490],[418,548],[370,592],[314,580],[286,530]]},
    {name:'zygomatic arch', part:'arch', line:1, pair:1, pts:[[300,500],[250,488],[210,506],[204,536],[248,546],[310,530]]},
    {name:'temporal line', part:'tline', line:1, pair:1, pts:[[340,110],[300,170],[276,250],[274,330],[300,362],[340,348]]},
    {name:'maxilla', part:'max', pair:1, pts:[[400,590],[484,568],[510,650],[500,720],[452,758],[392,718],[378,640]]},
    {name:'alveolar process', part:'alv', pair:1, pts:[[424,724],[496,712],[510,752],[468,778],[420,756],[414,732]]},
    {name:'orbital rim', part:'orbit', pair:1, pts:[[348,362],[418,372],[458,418],[450,478],[392,514],[324,512],[292,468],[286,404]]},
    {name:'mandible body', part:'mand', pts:[[340,780],[360,860],[400,930],[460,980],[516,994]]},
    {name:'ramus', part:'ramus', pair:1, pts:[[268,540],[250,640],[270,760],[320,778],[340,690],[318,570]]},
    {name:'mandibular angle', part:'angle', pair:1, pts:[[300,750],[292,820],[330,870],[370,850],[360,760]]},
    {name:'condyle', part:'condyle', pair:1, pts:[[248,478],[228,500],[236,540],[278,552],[300,520],[282,482]]},
    {name:'coronoid process', part:'coronoid', pair:1, pts:[[308,468],[338,492],[356,555],[324,588],[292,530],[300,490]]},
    {name:'mental protuberance', part:'ment', pts:[[516,888],[470,904],[452,948],[486,982],[516,994]]}
  ];
  const boneEls = [];
  for(const b of bones){
    const sides = b.pair ? ['L','R'] : ['C'];
    for(const s of sides){
      const pts = b.pair
        ? (s === 'R' ? b.pts.map(([x, y]) => [1032 - x, y]) : b.pts.slice())
        : (function(){
            const left = b.pts, right = [...left].reverse().map(([x, y]) => [1032 - x, y]);
            if(left[0][0] === 516) right.pop();
            if(left[left.length - 1][0] === 516) right.shift();
            return left.concat(right);
          })();
      const el = document.createElementNS(NS, b.line ? 'polyline' : 'polygon');
      el.setAttribute('class', b.line ? 'bone line' : 'bone');
      el.setAttribute('data-part', b.part);
      const title = document.createElementNS(NS, 'title');
      title.textContent = b.name + (b.pair ? ' ' + s : '');
      el.appendChild(title);
      g.appendChild(el);
      boneEls.push({el, pts, part:b.part});
    }
  }
  const fibers = [];
  for(const [id, def] of Object.entries(MUSCLE_DEFS)){
    const sides = def.pair ? ['L','R'] : ['C'];
    for(const s of sides){
      const X = s === 'R' ? 1032 - def.c[0] : def.c[0];
      const vx = def.v ? def.v[0] * (s === 'R' ? -1 : 1) : 0;
      const vy = def.v ? def.v[1] : (def.pull ? -10 : 0);
      const len = Math.hypot(vx, vy) || 1;
      const reach = Math.max(def.r[0], def.r[1]) * .9;
      const line = document.createElementNS(NS, 'line');
      line.setAttribute('class', 'fiber');
      line.setAttribute('stroke', def.hue);
      line.dataset.id = id; line.dataset.side = s;
      line._o = [X - vx / len * reach, def.c[1] - vy / len * reach];
      line._i = [X, def.c[1]];
      const title = document.createElementNS(NS, 'title');
      title.textContent = def.name + (s === 'C' ? '' : ' ' + s);
      line.appendChild(title);
      line.addEventListener('pointerdown', ev => {
        ev.stopPropagation();
        const f = LIVE_FACES.find(x => x.el.closest('#fd-face'));
        const n = MUSCLE_IDX[id + '.' + s];
        f.direct[n] = Math.abs(f.direct[n]) > .5 ? 0 : 1;
        facePads(f);
      });
      g.appendChild(line);
      fibers.push(line);
    }
  }
  const flush = document.createElementNS(NS, 'g');
  flush.setAttribute('class', 'fiber');
  flush.innerHTML = '<ellipse cx="340" cy="575" rx="82" ry="52" fill="#e0523f" opacity="0"/><ellipse cx="692" cy="575" rx="82" ry="52" fill="#e0523f" opacity="0"/>';
  g.appendChild(flush);
  svg.querySelector('.rig').appendChild(g);
  return {boneEls, fibers, flush};
}
let ANAT = null;
function drawAnatomy(){
  const f = LIVE_FACES.find(x => x.el && x.el.closest('#fd-face'));
  if(!f) return;
  syncAug(f);
  if(!ANAT) ANAT = mountAnatomy(f.el);
  for(const bone of ANAT.boneEls){
    bone.el.setAttribute('points', bone.pts.map(([x, y]) => {
      const d = boneDelta(x, y);
      return (x + d[0]).toFixed(1) + ',' + (y + d[1]).toFixed(1);
    }).join(' '));
  }
  for(const line of ANAT.fibers){
    const n = MUSCLE_IDX[line.dataset.id + '.' + line.dataset.side];
    const a = Math.max(0, f.acts[n] || 0);
    const [x1, y1] = line._o, [x2, y2] = line._i;
    line.setAttribute('x1', x1.toFixed(1));
    line.setAttribute('y1', y1.toFixed(1));
    line.setAttribute('x2', (x2 + (x1 - x2) * a * .45).toFixed(1));
    line.setAttribute('y2', (y2 + (y1 - y2) * a * .45).toFixed(1));
    line.setAttribute('stroke-width', (2.2 + a * 5).toFixed(2));
    line.setAttribute('stroke-opacity', (.28 + a * .7).toFixed(2));
  }
  const fl = ANAT.flush.children;
  const op = Math.min(.62, FACE_AUG.flush * .62).toFixed(2);
  fl[0].setAttribute('opacity', op); fl[1].setAttribute('opacity', op);
}
document.addEventListener('click', e => {
  const b = e.target.closest('[data-layer]');
  if(!b) return;
  b.classList.toggle('on');
  const on = b.classList.contains('on');
  document.querySelectorAll('.anat .' + (b.dataset.layer === 'fiber' ? 'fiber' : 'bone')).forEach(n => { n.style.display = on ? '' : 'none'; });
});
const faceTickCore = faceTick;
faceTick = function(now){
  const f = LIVE_FACES.find(x => x.el && x.el.closest('#fd-face'));
  if(f) syncAug(f);
  faceTickCore(now);
  if(f && f.augDirty){
    musApply(f.acts, f.DX, f.DY, f.mshade);
    for(let i = 0; i < f.polys.length; i++) f.dirty[i] = 1;
    f.musMoved = true;
    faceRender(f);
    facePaint(f, null, now);
    f.augDirty = false;
  }
  drawAnatomy();
};

document.getElementById('device-body').innerHTML = faceDeviceHTML();
